{"content":"#!/usr/bin/env python3
"""Maze solver: validate /protected/maze.txt and write shortest U/D/L/R path to /app/solution.txt."""
import os
import sys
from collections import deque

MAZE_PATH = "/protected/maze.txt"
SOLUTION_PATH = "/app/solution.txt"
SIZE = 255


def fail(msg):
    print(f"Error: {msg}", file=sys.stderr)
    # Ensure no solution file is left behind on failure.
    try:
        if os.path.exists(SOLUTION_PATH):
            os.remove(SOLUTION_PATH)
    except OSError:
        pass
    sys.exit(1)


def main():
    # File missing / unreadable.
    if not os.path.exists(MAZE_PATH):
        fail(f"maze file missing: {MAZE_PATH}")
    try:
        with open(MAZE_PATH, "r") as f:
            content = f.read()
    except OSError as e:
        fail(f"cannot read maze file: {e}")

    if content.strip() == "":
        fail("maze file is empty")

    lines = content.splitlines()

    if len(lines) == 0:
        fail("maze file is empty")

    # Validate header: "START x y END x y"
    header = lines[0].strip().split()
    if len(header) != 6 or header[0] != "START" or header[3] != "END":
        fail(f'malformed header, expected "START x y END x y", got: {lines[0]!r}')
    try:
        sx = int(header[1])
        sy = int(header[2])
        ex = int(header[4])
        ey = int(header[5])
    except ValueError:
        fail(f"malformed header coordinates, expected integers, got: {lines[0]!r}")

    # Validate grid dimensions.
    grid = lines[1:]
    if len(grid) != SIZE:
        fail(f"malformed grid: expected {SIZE} rows, got {len(grid)}")
    for i, row in enumerate(grid):
        if len(row) != SIZE:
            fail(f"malformed grid: row {i} has length {len(row)}, expected {SIZE}")
        for ch in row:
            if ch != "0" and ch != "1":
                fail(f"malformed grid: row {i} contains invalid character {ch!r} (only 0/1 allowed)")

    # Validate START/END in bounds and on open cells.
    for name, x, y in (("START", sx, sy), ("END", ex, ey)):
        if not (0 <= x < SIZE and 0 <= y < SIZE):
            fail(f"{name} ({x}, {y}) out of bounds for {SIZE}x{SIZE} grid")
    if grid[sy][sx] != "0":
        fail(f"START ({sx}, {sy}) is on a wall")
    if grid[ey][ex] != "0":
        fail(f"END ({ex}, {ey}) is on a wall")

    if sx == ex and sy == ey:
        # Trivial empty path.
        try:
            with open(SOLUTION_PATH, "w") as f:
                f.write("")
        except OSError as e:
            fail(f"cannot write solution file: {e}")
        sys.exit(0)

    # BFS for shortest path. Moves: U=(0,-1), D=(0,+1), L=(-1,0), R=(+1,0).
    moves = (("U", 0, -1), ("D", 0, 1), ("L", -1, 0), ("R", 1, 0))
    visited = bytearray(SIZE * SIZE)
    # parent[idx] = (prev_idx, move_char used to reach idx)
    parent = {}

    start_idx = sy * SIZE + sx
    end_idx = ey * SIZE + ex
    visited[start_idx] = 1
    q = deque([start_idx])
    found = False
    while q:
        cur = q.popleft()
        if cur == end_idx:
            found = True
            break
        cx = cur % SIZE
        cy = cur // SIZE
        for m, dx, dy in moves:
            nx, ny = cx + dx, cy + dy
            if 0 <= nx < SIZE and 0 <= ny < SIZE and grid[ny][nx] == "0":
                nidx = ny * SIZE + nx
                if not visited[nidx]:
                    visited[nidx] = 1
                    parent[nidx] = (cur, m)
                    q.append(nidx)

    if not visited[end_idx]:
        fail(f"END ({ex}, {ey}) is unreachable from START ({sx}, {sy})")

    # Reconstruct path from END to START.
    path_chars = []
    cur = end_idx
    while cur != start_idx:
        prev, m = parent[cur]
        path_chars.append(m)
        cur = prev
    path_chars.reverse()
    path = "".join(path_chars)

    try:
        with open(SOLUTION_PATH, "w") as f:
            f.write(path)
    except OSError as e:
        fail(f"cannot write solution file: {e}")


if __name__ == "__main__":
    main()
